{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-LUMEN-002-SESSION",
  "purpose": "Defines the zero-copy streaming ingestion engine, auto-fingerprinting detector, and orchestrator adapters for parsing Claude Code, Antigravity (AGY), Codex, and OpenCode session logs into CanonicalTranscript representations.",
  "scope": "Covers crates/lumen-session: SessionAdapter trait, AdapterCapabilities, fingerprint detection, ClaudeCodeAdapter, AgyAdapter, CodexAdapter, OpenCodeAdapter, PreCompact snapshot merge, and IngestionError.",
  "api_surface": [
    {
      "name": "SessionAdapter",
      "signature": "pub trait SessionAdapter: Send + Sync { fn name(&self) -> &'static str; fn matches_fingerprint(&self, sample: &str) -> bool; fn capabilities(&self) -> AdapterCapabilities; fn parse_stream<'a>(&self, reader: Box<dyn BufRead + 'a>) -> Result<CanonicalTranscript, IngestionError>; }",
      "description": "Streaming parser trait implemented by orchestrator adapters to project newline-delimited logs into CanonicalTranscript.",
      "error_conditions": [
        "IngestionError::MalformedJson if JSON line fails to parse",
        "IngestionError::UnrecognizedFormat if log sample does not match known orchestrators"
      ]
    },
    {
      "name": "AdapterCapabilities",
      "signature": "pub struct AdapterCapabilities { pub has_token_usage: bool, pub has_tool_results: bool, pub has_shell_commands: bool, pub has_file_events: bool, pub has_lifecycle_hooks: bool, pub supports_incremental_offsets: bool, pub supports_cost_estimation: bool }",
      "description": "Observability declaration exposing what telemetric capabilities are supported by the target orchestrator.",
      "error_conditions": []
    },
    {
      "name": "detect_orchestrator",
      "signature": "pub fn detect_orchestrator(sample_bytes: &[u8]) -> Option<OrchestratorKind>",
      "description": "Sub-millisecond fingerprint detector inspecting the first 2048 bytes of a session log to identify Claude Code, AGY, Codex, or OpenCode.",
      "error_conditions": [
        "Returns None if byte sample contains insufficient or ambiguous headers"
      ]
    },
    {
      "name": "merge_precompact_snapshots",
      "signature": "pub fn merge_precompact_snapshots(final_transcript: CanonicalTranscript, snapshots: &[TurnTokenUsage]) -> CanonicalTranscript",
      "description": "Applies the max() cumulative token merge invariant across pre-compaction snapshots to prevent double-counting on compacted sessions.",
      "error_conditions": []
    },
    {
      "name": "synthetic_50mb_session",
      "signature": "pub fn synthetic_50mb_session(orchestrator: OrchestratorKind, seed: u64) -> impl BufRead",
      "description": "Deterministic (seeded) fixture generator in crates/lumen-fixtures that programmatically expands a real corpus template (e.g. real_claude_session_dump()) to at least 50MB, in-memory, for CRIT-LUMEN-029 benchmarking without requiring a checked-in binary fixture. Return type intentionally deviates from the other corpus/*.rs fixtures (which return &'static str literals): this fixture is generated/owned data, not a static string, since a 50MB literal is impractical to check in.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-020",
      "criterion": "WHEN a session file starts with Claude Code permission or mode headers, THE SYSTEM SHALL identify the orchestrator as OrchestratorKind::ClaudeCode in under 1 millisecond.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-021",
      "criterion": "WHEN a session file starts with AGY step_index and source headers, THE SYSTEM SHALL identify the orchestrator as OrchestratorKind::Antigravity in under 1 millisecond.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-022",
      "criterion": "WHEN ClaudeCodeAdapter parses an assistant message containing tool_use blocks, THE SYSTEM SHALL extract tool_name, call_id, and typed ToolIntent in the CanonicalTurn.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-023",
      "criterion": "WHEN ClaudeCodeAdapter parses message.usage, THE SYSTEM SHALL extract input_tokens, output_tokens, cache_creation_input_tokens, and cache_read_input_tokens.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-024",
      "criterion": "WHEN merging pre-compaction snapshots, THE SYSTEM SHALL compute input_tokens = max(final_input, max(snapshot_inputs)) and cache_read_tokens = max(final_cache_read, max(snapshot_cache_reads)).",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-025",
      "criterion": "IF a JSONL log contains corrupted, truncated, or non-UTF8 lines, THE SYSTEM SHALL skip the malformed line, record a warning, and continue parsing without panicking.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-026",
      "criterion": "WHEN subagent metadata files (*.meta.json) exist in the subagents/ directory, THE SYSTEM SHALL link each child subagent transcript to its parent tool_use_id and record its spawnDepth.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-027",
      "criterion": "WHEN AgyAdapter parses a PLANNER_RESPONSE step containing thinking blocks, THE SYSTEM SHALL extract the reasoning text into CanonicalTurn.text.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-028",
      "criterion": "IF an empty session file is supplied, THE SYSTEM SHALL return a valid CanonicalTranscript with 0 turns and 0 token usage without erroring.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-029",
      "criterion": "WHEN memory-mapped file parsing is requested on a 50MB session file, THE SYSTEM SHALL parse all turns in under 35 milliseconds.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-106",
      "criterion": "WHEN a session file's first 2048 bytes contain the JSON substrings \"choices\", \"prompt_tokens\", or \"thread_id\" and no ClaudeCode or Antigravity fingerprint markers matched first, THE SYSTEM SHALL identify the orchestrator as OrchestratorKind::Codex via detect_orchestrator.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-107",
      "criterion": "WHEN a session file's first 2048 bytes contain \"action\":\"run\" (unspaced only) or \"observation\": and no ClaudeCode, Antigravity, or Codex fingerprint markers matched first, THE SYSTEM SHALL identify the orchestrator as OrchestratorKind::OpenCode via detect_orchestrator. This is the ground-truth enumeration for detect_orchestrator specifically; it deliberately does not include the spaced variant \"action\": \"run\" or \"action\":\"message\", neither of which detect_orchestrator checks for (see CRIT-LUMEN-108).",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-108",
      "criterion": "WHEN CodexAdapter::matches_fingerprint or OpenCodeAdapter::matches_fingerprint is invoked on any sample string, THE SYSTEM SHALL return exactly the boolean that detect_orchestrator(sample.as_bytes()) == Some(OrchestratorKind::Codex) (respectively Some(OrchestratorKind::OpenCode)) would return, so the two independently-coded detection paths cannot drift apart. KNOWN CURRENT GAP: OpenCodeAdapter::matches_fingerprint today additionally accepts the spaced variant \"action\": \"run\" and \"action\":\"message\", neither of which detect_orchestrator's OpenCode branch checks for per CRIT-LUMEN-107's ground truth -- this criterion currently fails in one direction: a sample containing only \"action\": \"run\" (spaced) or only \"action\":\"message\" is accepted by matches_fingerprint but not recognized as OpenCode by detect_orchestrator at all. Fixing this requires either removing these two extra conditions from OpenCodeAdapter::matches_fingerprint, or adding them to detect_orchestrator's OpenCode branch, whichever is judged the correct ground truth.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-109",
      "criterion": "WHEN CodexAdapter::parse_stream reads JSONL lines containing a \"thread_id\" field and a top-level \"choices\" array, THE SYSTEM SHALL set CanonicalTranscript.session_id from the observed thread_id and append one CanonicalTurn per element of choices[], with turn.role set to TurnRole::Assistant when choices[i].message.role == \"assistant\" (else TurnRole::User) and turn.text set from choices[i].message.content when that field is present -- replacing the current stub that ignores the reader argument entirely and always returns session_id=\"codex-session\" with zero turns regardless of input.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-110",
      "criterion": "WHEN CodexAdapter::parse_stream reads a JSONL line containing \"usage\":{\"prompt_tokens\":...,\"completion_tokens\":...}, THE SYSTEM SHALL sum prompt_tokens across every usage-bearing line encountered into TokenEconomics.input_tokens and sum completion_tokens into TokenEconomics.output_tokens (cumulative sum, not last-write-overwrite, matching OpenCodeAdapter's established accumulation pattern) -- replacing the current stub's unconditional TokenEconomics::calculate(0, 0, 0, 0, ...).",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-111",
      "criterion": "WHEN OpenCodeAdapter parses a JSON line containing a metrics or usage object, THE SYSTEM SHALL read input_tokens from accumulated_cost when present (else from input_tokens), read output_tokens/cache_creation_input_tokens/cache_read_input_tokens directly, and accumulate (sum) them into transcript-level TokenEconomics only when input_tokens > 0 or output_tokens > 0 for that line.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-112",
      "criterion": "WHEN OpenCodeAdapter parses a line with \"action\":\"message\", THE SYSTEM SHALL emit a CanonicalTurn with role Assistant when source==\"assistant\" (else User) and text set from args.content when that field is present.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-113",
      "criterion": "WHEN OpenCodeAdapter parses a line whose action is run, read, edit, or think, THE SYSTEM SHALL classify ToolIntent as VersionControl when action==run and args.command starts with \"git\", TestExecution when action==run and args.command contains \"test\", FileRead when action==read, FileEdit when action==edit, and Other for every remaining case (including think).",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-114",
      "criterion": "WHEN OpenCodeAdapter parses a line containing a string \"observation\" field, THE SYSTEM SHALL emit a CanonicalTurn with role ToolResult, is_error taken from the line's boolean error field, and error_class set to \"ObservationError\" only when is_error is true.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-115",
      "criterion": "IF a line in an OpenCode JSONL log fails serde_json parsing, THE SYSTEM SHALL skip the malformed line and record a warning before continuing -- this is CRIT-LUMEN-025's system-wide malformed-line requirement made explicitly testable against OpenCodeAdapter, which the current implementation violates by silently `continue`-ing on parse failure with no warning recorded.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-116",
      "criterion": "THE SYSTEM SHALL provide a synthetic_50mb_session(orchestrator: OrchestratorKind, seed: u64) fixture generator in crates/lumen-fixtures that deterministically expands a real corpus template to at least 50MB without any binary fixture file being checked into the repository, and a criterion benchmark in crates/lumen-session/benches/ SHALL assert that parse_stream over that generated fixture completes in under 35 milliseconds, providing the concrete measurement path CRIT-LUMEN-029 currently lacks. NOTE: this benchmarks parse_stream's actual current reader path (a buffered line reader); it does not itself require memory-mapped I/O, since memmap2 is a declared lumen-session dependency (Cargo.toml) that is not yet used by any parsing code path -- CRIT-LUMEN-029's \"memory-mapped\" framing is aspirational relative to the current implementation, a pre-existing gap outside this amendment's scope to resolve.",
      "is_error_case": false,
      "judgment_call": true
    }
  ],
  "non_goals": [
    "Database persistence, schema migrations, or queue supervisors (delegated to session-daemon).",
    "Evaluation assertion grading or pass/fail decisions (delegated to prism-grader).",
    "Checking a physical 50MB-or-larger binary session-log fixture into the git repository for CRIT-LUMEN-029 benchmarking; the fixture is instead generated deterministically at benchmark time by crates/lumen-fixtures's synthetic_50mb_session generator."
  ],
  "linked_requirement": "REQ-LUMEN-002",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-002-SESSION.json",
  "reasoning": "Establishes zero-copy streaming ingestion across multi-orchestrator log formats with snapshot merging and subagent tree resolution."
}

