{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-LUMEN-006-PATTERN",
  "purpose": "Defines the graph-theoretical trajectory modeling, Tarjan SCC cycle loop detection, argument grounding scoring, and resolution monotonicity algorithms for Lumen.",
  "scope": "Covers crates/lumen-pattern: TrajectoryGraph, ToolNode, CircularLoopAnomaly, compute_grounding_score, compute_recovery_index, and calculate_monotonicity.",
  "non_goals": [
    "Raw token pricing or financial accounting (delegated to lumen-model).",
    "Database persistence or query filtering (delegated to lumen-store)."
  ],
  "api_surface": [
    {
      "name": "ToolNode",
      "signature": "pub struct ToolNode { pub turn_index: usize, pub tool_name: CompactString, pub target_symbol: Option<CompactString>, pub target_file: Option<CompactString>, pub is_mutation: bool, pub had_error: bool }",
      "description": "A single tool invocation node in the trajectory graph, carrying the grounded target file/symbol used for cycle and grounding-score analysis.",
      "error_conditions": []
    },
    {
      "name": "CircularLoopAnomaly",
      "signature": "pub struct CircularLoopAnomaly { pub symbol: CompactString, pub cycle_depth: usize }",
      "description": "Records a detected Tarjan SCC cycle of >= 3 nodes sharing an identical target_symbol with zero state mutations.",
      "error_conditions": []
    },
    {
      "name": "TrajectoryGraph",
      "signature": "pub struct TrajectoryGraph { pub graph: petgraph::graph::DiGraph<ToolNode, ()>, pub last_node: Option<NodeIndex>, pub total_mutations: usize, pub total_reads: usize }; impl TrajectoryGraph { pub fn new() -> Self; pub fn push_tool(&mut self, node: ToolNode) -> NodeIndex; pub fn detect_circular_loops(&self) -> Vec<CircularLoopAnomaly>; pub fn calculate_efficiency(&self) -> f32; pub fn calculate_monotonicity(&self) -> f32; }",
      "description": "Directed graph representation of agent execution paths built by pushing ToolNodes in turn order; detect_circular_loops runs petgraph's Tarjan SCC to find cyclic tool loops and redundant file exploration.",
      "error_conditions": []
    },
    {
      "name": "compute_grounding_score",
      "signature": "pub fn compute_grounding_score(transcript: &CanonicalTranscript) -> f32",
      "description": "Computes Argument Grounding Score G = (Grounded Tool Args) / (Total Invocations). Returns 1.0 when total_tools == 0 (no division by zero).",
      "error_conditions": ["Returns 1.0 (not NaN/panic) when total_tools == 0."]
    },
    {
      "name": "compute_recovery_index",
      "signature": "pub fn compute_recovery_index(transcript: &CanonicalTranscript) -> f32",
      "description": "Computes the Error Recovery Index R = adaptive_error_pivots / total_error_events, where an adaptive error pivot is an error on turn i followed by no error on turn i+1. Returns 1.0 when total_error_events == 0 (no division by zero).",
      "error_conditions": ["Returns 1.0 (not NaN/panic) when total_error_events == 0."]
    },
    {
      "name": "calculate_monotonicity",
      "signature": "pub fn calculate_monotonicity(transcript: &CanonicalTranscript) -> f32",
      "description": "Convenience helper that builds a TrajectoryGraph from a transcript's tool calls in turn order and computes the monotonicity coefficient M in [0.0, 1.0], measuring whether execution avoided circular exploration loops.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-070",
      "criterion": "WHEN a transcript contains 3 identical view_file invocations on the same path without interleaving mutations, THE SYSTEM SHALL identify a Tarjan SCC cyclic loop and emit a CycleAnomaly.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-071",
      "criterion": "WHEN computing resolution monotonicity M on a linear pass transcript with zero backtracking, THE SYSTEM SHALL return M = 1.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-072",
      "criterion": "WHEN compute_recovery_index(transcript) is invoked on a transcript where an error occurs on turn i and no error occurs on turn i+1 (1 adaptive error pivot out of 1 total error event), THE SYSTEM SHALL return Error Recovery Index R = adaptive_error_pivots / total_error_events = 1.0.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-073",
      "criterion": "WHEN compute_grounding_score is executed, THE SYSTEM SHALL compute the ratio of tool argument values grounded in prior user or tool outputs versus hallucinated values.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-074",
      "criterion": "IF a transcript has 0 or 1 turns, THE SYSTEM SHALL return monotonicity M = 1.0 and grounding score = 1.0 without dividing by zero.",
      "is_error_case": true,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-155",
      "criterion": "WHEN calculate_monotonicity(transcript) is invoked on a transcript containing 3 consecutive tool invocations that share the same grounded target file or symbol with no interleaving mutation, THE SYSTEM SHALL return M < 1.0, reflecting a detected circular exploration loop.",
      "is_error_case": false,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-LUMEN-006",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-006-PATTERN.json",
  "reasoning": "Establishes graph-theoretical trajectory modeling, Tarjan SCC cycle detection, and mathematical quality indicators. CRIT-LUMEN-072 was rewritten (same id) to bind it to the real compute_recovery_index function/formula (crates/lumen-pattern/src/lib.rs:141-166) instead of untestable prose; the formula was already correctly implemented, only the api_surface entry and criterion wording were missing. CRIT-LUMEN-155 is a known-failing (red) criterion as of 2026-08-19: the public calculate_monotonicity(transcript) entry point (lib.rs:169-185) currently constructs every ToolNode with target_symbol: None / target_file: None, so detect_circular_loops (lib.rs:65-84) never fires. Fixing this requires TWO changes, not one: (1) populating target_symbol/target_file from the tool call's grounded path/symbol data, AND (2) adding back-edge construction logic to TrajectoryGraph::push_tool (or an equivalent graph-building step) that links a node back to a prior node sharing the same target_symbol/target_file when no interleaving mutation occurred — field population alone is insufficient, since push_tool (lib.rs:50-63) only ever adds a single forward edge per call, producing a strictly linear chain with no cycles regardless of node content (confirmed by crates/lumen-pattern/tests/test_graph_topology.rs's test_3_node_cycles_on_identical_symbols, which only detects a cycle after manually adding a back-edge via g.graph.add_edge(n3, n1, ())). CRIT-075 must not be marked satisfied without both changes."
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-LUMEN-007-INSIGHTS",
  "purpose": "Defines the workflow classification engine, bimodal interaction modeling, dynamic category discovery, and RTK modern CLI missed-savings rules for Lumen.",
  "scope": "Covers crates/lumen-insights: WorkflowClassifier, CategoryDetector, RtkOpportunityRule, FindingGenerator, BimodalClassifier, and RollupEngine.",
  "non_goals": [
    "Raw SQLite database table management (handled by lumen-store).",
    "Active code execution or test running (handled by prism-core).",
    "Persisting or incrementally updating discovered category clusters across process restarts (discover_fingerprint_corpus recomputes clustering from the full in-memory transcript corpus supplied on each call)."
  ],
  "api_surface": [
    {
      "name": "WorkflowClassifier",
      "signature": "pub struct WorkflowClassifier; impl WorkflowClassifier { pub fn classify_seed(transcript: &CanonicalTranscript) -> Vec<CategoryScore>; pub fn discover_fingerprint(transcript: &CanonicalTranscript, corpus: &[CanonicalTranscript]) -> Option<DiscoveredCategory>; pub fn discover_fingerprint_corpus(corpus: &[CanonicalTranscript]) -> Vec<DiscoveredCategory>; pub fn classify_bimodal(transcript: &CanonicalTranscript) -> BimodalMode; }",
      "description": "Classifies session transcripts into seed categories (feature_dev, bug_hunt, refactoring, test_authoring, eval) and discovers new category clusters. discover_fingerprint looks up which cluster (if any) a single transcript belongs to within a supplied corpus; discover_fingerprint_corpus computes the full clustering over that corpus in one pass.",
      "error_conditions": []
    },
    {
      "name": "BimodalMode",
      "signature": "pub enum BimodalMode { Acceleration, Exploration, Balanced }",
      "description": "Classifies a session's dominant interaction pattern: Acceleration (high mutation density, low search activity), Exploration (high search activity, high turn count), or Balanced (neither threshold met).",
      "error_conditions": []
    },
    {
      "name": "DiscoveredCategory",
      "signature": "pub struct DiscoveredCategory { pub member_count: usize, pub member_session_ids: Vec<CompactString>, pub tool_bigram_fingerprint: Vec<CompactString> }",
      "description": "A dynamically discovered workflow cluster of >= 3 transcripts whose ordered tool-invocation sequences meet the pairwise similarity threshold in CRIT-LUMEN-156.",
      "error_conditions": []
    },
    {
      "name": "RtkOpportunityRule",
      "signature": "pub struct RtkOpportunityRule; impl RtkOpportunityRule { pub fn evaluate(commands: &[CommandEventRecord]) -> Vec<StructuredFinding>; }",
      "description": "Evaluates command event sequences to detect legacy POSIX tool invocations (grep, find, cat, cd) and generate actionable modern CLI recommendations.",
      "error_conditions": []
    },
    {
      "name": "FindingGenerator",
      "signature": "pub struct FindingGenerator; impl FindingGenerator { pub fn generate_findings(transcript: &CanonicalTranscript, loop_anomalies: &[CycleAnomaly]) -> Vec<StructuredFinding>; }",
      "description": "Synthesizes structured findings containing severity, confidence, rule version, evidence JSON, and remediation recommendations.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-080",
      "criterion": "WHEN a session's mutation_density (count of ToolIntent::FileEdit and ToolIntent::FileCreate calls divided by total tool calls in the session; ToolIntent::VersionControl is excluded from this ratio since its actions span both read-only and mutating operations) is >= 0.60 AND its search_turn_count (count of turns containing at least one ToolIntent::CodeSearch or ToolIntent::FileDiscovery call) is <= 2, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Acceleration.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-081",
      "criterion": "WHEN a session's search_turn_count (count of turns containing at least one ToolIntent::CodeSearch or ToolIntent::FileDiscovery call) is >= 6 AND its total turn_count is >= 15, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Exploration.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-082",
      "criterion": "WHEN a command event sequence contains grep or egrep invocations, THE SYSTEM SHALL emit an RTK opportunity finding recommending ripgrep (rg) with an estimated speedup metric.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-083",
      "criterion": "WHEN a command event sequence contains find invocations, THE SYSTEM SHALL emit an RTK opportunity finding recommending fd to prevent traversing ignored build directories.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-084",
      "criterion": "WHEN structured findings are generated, THE SYSTEM SHALL populate evidence_json, confidence score in [0.0, 1.0], rule_or_model_version, and actionable recommendation text.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-085",
      "criterion": "WHEN computing periodic rollups, THE SYSTEM SHALL aggregate session count, total cost USD, active wall time, and finding counts by repository, category, and weekly period start.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-156",
      "criterion": "WHEN WorkflowClassifier::discover_fingerprint_corpus evaluates a corpus of transcripts and finds a maximal clique of >= 3 transcripts where every pair within the clique has Jaccard similarity >= 0.75 over the set of tool-name bigrams extracted from each transcript's ordered ToolIntent call sequence (complete-linkage clustering), THE SYSTEM SHALL emit one DiscoveredCategory per maximal qualifying clique with member_count equal to the clique size and member_session_ids listing every member transcript's session_id; a transcript belonging to more than one qualifying clique SHALL be assigned only to the largest, ties broken by lexically earliest session_id. WorkflowClassifier::discover_fingerprint(transcript, corpus) SHALL return Some(that DiscoveredCategory) for any transcript present in corpus that was assigned to a clique.",
      "is_error_case": false,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-157",
      "criterion": "IF no maximal clique of >= 3 transcripts in the corpus meets the >= 0.75 pairwise tool-bigram similarity threshold, THE SYSTEM SHALL have discover_fingerprint_corpus return an empty Vec<DiscoveredCategory>, and discover_fingerprint(transcript, corpus) SHALL return None for every transcript in that corpus.",
      "is_error_case": true,
      "judgment_call": true
    },
    {
      "id": "CRIT-LUMEN-158",
      "criterion": "WHEN a session's mutation_density, search_turn_count, and turn_count satisfy neither CRIT-LUMEN-080's Acceleration thresholds nor CRIT-LUMEN-081's Exploration thresholds, THE SYSTEM SHALL classify its bimodal mode as BimodalMode::Balanced.",
      "is_error_case": false,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-LUMEN-007",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-007-INSIGHTS.json",
  "reasoning": "Establishes workflow categorization, bimodal theory modeling, RTK missed savings coaching, and structured finding generation."
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "spec@1",
  "id": "SPEC-LUMEN-008-CLI",
  "purpose": "Defines the developer terminal experience, interactive TUI explorer, subcommands, diagnostic doctor checks, and multi-format outputs (Human, JSON, and TOON) for Lumen.",
  "scope": "Covers crates/lumen-cli: CLI entrypoints (status, refresh, sessions, session, categories, insights, weekly, export, doctor, daemon), TUI renderer, and formatters.",
  "non_goals": [
    "Database write locks or background worker execution (delegated to lumen-daemon).",
    "Active test suite running (delegated to prism-cli)."
  ],
  "api_surface": [
    {
      "name": "CliApp",
      "signature": "pub struct CliApp; impl CliApp { pub async fn run(args: CliArgs) -> Result<(), CliError>; }",
      "description": "Top-level command line router executing read-only SQLite queries or issuing IPC triggers to lumen-daemon.",
      "error_conditions": [
        "CliError::DaemonNotRunning if IPC commands fail to reach daemon socket",
        "CliError::DatabaseNotFound if SQLite database has not been initialized"
      ]
    },
    {
      "name": "DoctorEngine",
      "signature": "pub struct DoctorEngine; impl DoctorEngine { pub fn run_checks(fix: bool) -> DoctorReport; }",
      "description": "Runs diagnostic self-checks verifying SQLite WAL health, daemon PID status, LaunchAgent registration, hook installations, and provider directory permissions.",
      "error_conditions": []
    },
    {
      "name": "ToonFormatter",
      "signature": "pub struct ToonFormatter; impl ToonFormatter { pub fn format_sessions(sessions: &[SessionSummaryReadModel]) -> String; pub fn format_findings(findings: &[FindingReadModel]) -> String; }",
      "description": "Formats session and finding lists as Token-Optimized Object Notation (TOON) using michi-toon to cut token consumption by 60% for agent consumption.",
      "error_conditions": []
    }
  ],
  "acceptance_criteria": [
    {
      "id": "CRIT-LUMEN-090",
      "criterion": "WHEN lumen status is executed, THE SYSTEM SHALL display daemon state, queue depth, SQLite DB size, total spend, and cache hit ratio in under 5 milliseconds.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-091",
      "criterion": "WHEN lumen refresh is executed, THE SYSTEM SHALL send an IPC trigger to the daemon and wait synchronously until all queued sessions are ingested.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-092",
      "criterion": "WHEN any view command is executed with --json, THE SYSTEM SHALL output valid JSON conforming byte-for-byte to the shared read model schema.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-093",
      "criterion": "WHEN any view command is executed with --toon, THE SYSTEM SHALL render tabular data in Token-Optimized Object Notation via michi-toon.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-094",
      "criterion": "WHEN lumen session <id> is executed, THE SYSTEM SHALL display session metadata, 4-tier token balance sheet, turn latency waterfall, and loop anomaly alerts.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-095",
      "criterion": "WHEN lumen weekly is executed, THE SYSTEM SHALL display a 7-day rollup of sessions, active coding time, token spend, and git commits grouped by repository.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-096",
      "criterion": "WHEN lumen doctor is executed, THE SYSTEM SHALL evaluate daemon health, SQLite integrity, hook registrations, and provider directory permissions, returning pass/fail indicators for each check.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-097",
      "criterion": "WHEN lumen doctor --fix is executed, THE SYSTEM SHALL automatically correct broken hook symlinks and repair database permissions without user intervention.",
      "is_error_case": false,
      "judgment_call": false
    },
    {
      "id": "CRIT-LUMEN-098",
      "criterion": "IF the SQLite database file does not exist when a view command runs, THE SYSTEM SHALL display a helpful onboarding error instructing the user to run lumen daemon install.",
      "is_error_case": true,
      "judgment_call": false
    }
  ],
  "linked_requirement": "REQ-LUMEN-008",
  "linked_research": "RES-LUMEN-001",
  "spec_file_path": "specs/SPEC-LUMEN-008-CLI.json",
  "reasoning": "Establishes the developer CLI experience, diagnostic doctor engine, and multi-format outputs (Human, JSON, TOON)."
}

